<script setup>
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue';
import { Button, CellGroup, Dialog, Field, Form, Tab, Tabs } from 'vant';
import 'vant/es/button/style';import 'vant/es/cell-group/style';import 'vant/es/dialog/style';import 'vant/es/field/style';import 'vant/es/form/style';import 'vant/es/tabs/style';import 'vant/es/tab/style';
const props=defineProps({services:{type:Object,required:true}});
const emit=defineEmits(['close']);
const kind=ref('deepseek'),busy=ref(false),message=ref(''),error=ref(''),confirm=ref(false),native=ref(false),draft=reactive({apiKey:'',model:'',base:'',voice:''});
let controller,version=0,alive=true;
function cancel(){version++;controller?.abort();controller=null;busy.value=false;draft.apiKey='';}
async function read(){cancel();message.value='';error.value='';draft.model='';draft.base='';draft.voice='';controller=new AbortController();const request=version;busy.value=true;try{const info=await props.services[kind.value].info(controller.signal);if(!alive||version!==request)return;if(info.error)throw Error(info.error);draft.model=info.model||'';draft.base=info.base||'';draft.voice=info.voice||'';native.value=!!info.native;message.value=info.configured?'已保存个人密钥；留空沿用。':info.serverConfigured?'服务端连接已配置；可保存个人密钥覆盖。':'尚未配置个人密钥。';}catch(e){if(alive&&version===request&&e.name!=='AbortError')error.value=e.message;}finally{if(version===request)busy.value=false;}}
async function execute(action){if(busy.value)return;controller=new AbortController();const request=++version;busy.value=true;error.value='';try{const service=props.services[kind.value];if(action==='save')await service.save({...draft});else if(action==='clear')await service.clear();else await service.test(controller.signal);if(!alive||request!==version)return;if(action!=='test')draft.apiKey='';message.value=action==='save'?'配置已保存。':action==='clear'?'个人配置已清除。':kind.value==='voice'?'语音配置可用，实际连通性以语音会话为准。':'连接测试成功。';}catch(e){if(alive&&request===version&&e.name!=='AbortError')error.value=e.message;}finally{if(request===version)busy.value=false;}}
function close(){cancel();emit('close');}
onMounted(read);onBeforeUnmount(()=>{alive=false;cancel();});
</script>
<template><section class="student-course-settings course-ai-settings" aria-label="AI连接设置"><header><h2>学习设置</h2><Button icon="cross" aria-label="关闭设置" title="关闭设置" class="student-course-close" @click="close"/></header><Tabs v-model:active="kind" @change="read"><Tab v-if="services.deepseek" name="deepseek" title="DeepSeek 密钥"/><Tab v-if="services.voice" name="voice" title="语音 Key"/></Tabs><p>密钥仅保存在当前账号的本机设置；留空沿用已保存密钥。</p><Form @submit="execute('save')"><CellGroup><Field v-model="draft.apiKey" type="password" label="个人密钥" autocomplete="new-password" :disabled="busy" placeholder="留空沿用"/><Field v-if="kind==='deepseek'" v-model="draft.model" label="模型" :readonly="native" :disabled="busy"/><template v-else><Field v-model="draft.base" label="服务地址" :disabled="busy"/><Field v-model="draft.voice" label="音色 ID" :disabled="busy"/><div class="student-course-voices"><Button v-for="voice in services.voice?.voices||[]" :key="voice" :disabled="busy" @click="draft.voice=voice">{{ voice }}</Button></div></template></CellGroup><div class="student-course-actions"><Button type="primary" native-type="submit" :disabled="busy" :loading="busy">保存配置</Button><Button :disabled="busy" @click="execute('test')">{{ kind==='voice'?'检查语音配置':'测试已保存连接' }}</Button><Button :disabled="busy" @click="confirm=true">清除配置</Button></div></Form><p role="status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><Dialog v-model:show="confirm" title="清除个人配置">仅清除当前账号的这项配置，确定继续？<template #footer><div class="student-course-actions" style="padding:16px"><Button icon="cross" aria-label="关闭清除确认" class="student-course-close" @click="confirm=false"/><Button type="primary" @click="confirm=false;execute('clear')">清除个人配置</Button></div></template></Dialog></section></template>
<style scoped>.student-course-settings header{display:flex;justify-content:space-between;align-items:center;gap:12px}.student-course-settings p{line-height:1.7;overflow-wrap:anywhere}.student-course-close{width:44px;height:44px;padding:0}.student-course-actions,.student-course-voices{display:flex;gap:10px;flex-wrap:wrap;padding:16px 0}.student-course-settings :deep(.van-button){min-height:44px}.student-course-settings{--van-tabs-bottom-bar-color:#22634b;--van-button-primary-background:#22634b;--van-button-primary-border-color:#22634b}.student-course-settings [role=alert]{color:#9f3131}

.student-course-settings{margin:20px 0;padding:18px;border:1px solid #768b73;border-radius:12px;font:inherit;line-height:1.8;color:inherit;background:transparent;--van-primary-color:var(--ui-accent);--van-tabs-bottom-bar-color:var(--ui-accent);--van-button-primary-background:var(--ui-accent);--van-button-primary-border-color:var(--ui-accent)}.student-course-settings header{padding:0;background:transparent;border:0;position:static}.student-course-settings h2{font-size:20px;margin:0}.student-course-settings :deep(.van-cell-group){background:transparent}.student-course-settings :deep(.van-field){display:flex;flex-direction:column;padding:0;margin:12px 0;background:transparent;color:inherit;font:inherit}.student-course-settings :deep(.van-field__label){display:block;width:auto;margin:0;font:inherit}.student-course-settings :deep(.van-field__control){display:block;width:100%;padding:12px;margin:6px 0;border:1px solid #768b73;border-radius:8px;font:inherit;background:transparent;color:inherit;min-height:44px}.student-course-settings :deep(.van-tabs__nav){background:transparent;gap:8px;padding:0;justify-content:start}.student-course-settings :deep(.van-tabs__wrap){height:46px;margin:16px 0}.student-course-settings :deep(.van-tab){flex:0 0 auto;border:1px solid var(--ui-control);border-radius:8px;padding:9px 14px;background:white;font:inherit;color:inherit}.student-course-settings :deep(.van-tab--active){background:var(--ui-soft)}.student-course-settings :deep(.van-tabs__line){display:none}.student-course-settings :deep(.van-button){font:inherit;height:auto;min-height:44px;padding:10px 16px;background:var(--ui-surface);border:1px solid var(--ui-control);border-radius:8px;color:inherit}.student-course-settings :deep(.van-button--primary){background:var(--ui-accent);color:white;border-color:var(--ui-accent)}.student-course-settings :deep(.student-course-close){width:44px;height:44px;padding:0}

</style>
